CREATE TABLE IF NOT EXISTS enterprise_risks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', risk_title text NOT NULL, risk_category text NOT NULL, owner_role text, inherent_likelihood integer, inherent_impact integer, inherent_score integer, control_summary text, residual_likelihood integer, residual_impact integer, residual_score integer, risk_appetite text, treatment_plan text, target_date date, status text NOT NULL DEFAULT 'Open', board_reportable boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_obligations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', obligation_title text NOT NULL, regulator text, legal_source text, obligation_type text, owner_role text, frequency text, next_due_date date, evidence_required text, status text NOT NULL DEFAULT 'Active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), obligation_id uuid REFERENCES compliance_obligations(id), event_type text NOT NULL, event_date date, due_date date, owner_role text, status text NOT NULL DEFAULT 'Open', evidence_reference text, escalation_level text DEFAULT 'Normal', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS control_tests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_name text NOT NULL, control_area text, test_period date, tester_role text, test_method text, result text NOT NULL DEFAULT 'Pending', exception_count integer NOT NULL DEFAULT 0, evidence_reference text, remediation_required boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, audit_area text NOT NULL, finding_title text NOT NULL, severity text NOT NULL DEFAULT 'Medium', finding_description text, root_cause text, management_response text, owner_role text, due_date date, status text NOT NULL DEFAULT 'Open', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS remediation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid REFERENCES audit_findings(id), action_title text NOT NULL, action_owner text, due_date date, priority text NOT NULL DEFAULT 'Medium', status text NOT NULL DEFAULT 'Open', completion_evidence text, verified_by text, verified_at date, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ethics_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, report_type text NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(), confidentiality_level text NOT NULL DEFAULT 'Restricted', conflict_status text DEFAULT 'Pending Review', assigned_role text, investigation_status text NOT NULL DEFAULT 'Pending Triage', outcome text, evidence_reference text, retaliation_risk_flag boolean NOT NULL DEFAULT false, notes text);
CREATE TABLE IF NOT EXISTS risk_compliance_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_name text NOT NULL, control_level text NOT NULL DEFAULT 'High', control_description text NOT NULL, owner_role text, evidence_required text, frequency text, escalation_route text, status text NOT NULL DEFAULT 'Active');
INSERT INTO risk_compliance_controls(entity_name,control_name,control_level,control_description,owner_role,evidence_required,frequency,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Enterprise risk register','Critical','Material risks must have an owner, scoring, treatment plan and review status.','Risk owner / Executive','Risk assessment, treatment plan and review record','Quarterly / event-driven','Executive Risk Committee / Board' WHERE NOT EXISTS (SELECT 1 FROM risk_compliance_controls WHERE control_name='Enterprise risk register');
INSERT INTO risk_compliance_controls(entity_name,control_name,control_level,control_description,owner_role,evidence_required,frequency,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Compliance obligation register','Critical','Applicable legal and regulatory obligations must be mapped to an owner, evidence and due date.','General Counsel / Compliance','Legal source, obligation mapping and evidence','Continuous / periodic review','Board / regulator as applicable' WHERE NOT EXISTS (SELECT 1 FROM risk_compliance_controls WHERE control_name='Compliance obligation register');
INSERT INTO risk_compliance_controls(entity_name,control_name,control_level,control_description,owner_role,evidence_required,frequency,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Control testing','High','Key controls must be tested and exceptions documented, remediated and independently verified where required.','Internal Audit / Control Owner','Test plan, sample evidence, results and remediation','Quarterly / risk-based','Audit Committee / Board' WHERE NOT EXISTS (SELECT 1 FROM risk_compliance_controls WHERE control_name='Control testing');
INSERT INTO risk_compliance_controls(entity_name,control_name,control_level,control_description,owner_role,evidence_required,frequency,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Audit finding remediation','High','Audit findings require accountable owners, deadlines, evidence and closure verification.','Finding owner','Action plan, completion evidence and verification','Until closed','Internal Audit / Audit Committee' WHERE NOT EXISTS (SELECT 1 FROM risk_compliance_controls WHERE control_name='Audit finding remediation');
INSERT INTO risk_compliance_controls(entity_name,control_name,control_level,control_description,owner_role,evidence_required,frequency,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Ethics and protected reporting','Critical','Ethics concerns must have confidential intake, triage, conflict handling and non-retaliation safeguards.','Company Secretary / Compliance','Case record, conflict review, investigation evidence and outcome','Per report','Board / independent authority as appropriate' WHERE NOT EXISTS (SELECT 1 FROM risk_compliance_controls WHERE control_name='Ethics and protected reporting');